const now = new Date();
const end = now.toISOString().slice(0, 10);
const start = new Date(now.getTime() - 28 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const weekLabel = now.toLocaleDateString('en-US', {
  month: 'long', day: 'numeric', year: 'numeric',
  timeZone: 'America/Los_Angeles'
});
const weekOf = now.toLocaleDateString('en-US', {
  month: 'short', day: 'numeric',
  timeZone: 'America/Los_Angeles'
});
return [{ json: { startDate: start, endDate: end, weekLabel, weekOf } }];

const rows = $input.first().json.rows || [];
const startDate = $('Date setup').first().json.startDate;
const endDate = $('Date setup').first().json.endDate;
const weekLabel = $('Date setup').first().json.weekLabel;
const weekOf = $('Date setup').first().json.weekOf;

const parsed = rows.map(function(r) {
  return {
    query: r.keys[0],
    page: r.keys[1],
    position: Math.round(r.position * 10) / 10,
    clicks: r.clicks,
    impressions: r.impressions
  };
}).sort(function(a, b) { return b.impressions - a.impressions; });

const totalClicks = parsed.reduce(function(s, r) { return s + r.clicks; }, 0);
const totalImpressions = parsed.reduce(function(s, r) { return s + r.impressions; }, 0);

const ranked = parsed.filter(function(r) { return r.position < 5; });
const gaps = parsed.filter(function(r) { return r.position >= 5 && r.position <= 20; });
const weakRanking = parsed.filter(function(r) { return r.position > 20; });

let gscBlock = 'GSC DATA — https://thecrawli.com/ — last 28 days (' + startDate + ' to ' + endDate + ')\n';
gscBlock += 'Unique queries: ' + parsed.length + ' | Clicks: ' + totalClicks + ' | Impressions: ' + totalImpressions + '\n\n';

if (ranked.length > 0) {
  gscBlock += 'Ranking well (pos 1-4):\n';
  ranked.forEach(function(r) { gscBlock += '  "' + r.query + '" pos ' + r.position + ', ' + r.impressions + ' imp, ' + r.clicks + ' clicks\n'; });
  gscBlock += '\n';
}
if (gaps.length > 0) {
  gscBlock += 'Keyword gaps — low-hanging fruit (pos 5-20, sorted by impressions):\n';
  gaps.forEach(function(r) { gscBlock += '  "' + r.query + '" pos ' + r.position + ', ' + r.impressions + ' imp, ' + r.clicks + ' clicks\n'; });
  gscBlock += '\n';
}
if (weakRanking.length > 0 && weakRanking.length <= 10) {
  gscBlock += 'Weak rankings (pos 20+, worth knowing):\n';
  weakRanking.forEach(function(r) { gscBlock += '  "' + r.query + '" pos ' + r.position + ', ' + r.impressions + ' imp\n'; });
  gscBlock += '\n';
}
if (parsed.length < 5) {
  gscBlock += 'NOTE: Site has very little GSC data — generate keyword map based on niche knowledge.\n';
}

return [{ json: { gscBlock, weekLabel, weekOf, startDate, endDate, totalRows: parsed.length, totalClicks, totalImpressions } }];

const rawText = $('Generate keyword map').first().json.output[0].content[0].text.trim()
  .replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '').trim();

let map;
try { map = JSON.parse(rawText); } catch(e) { map = { gscSummary: 'Parse error: ' + e.message, keywords: [], clusters: [], topPriorities: [], contextNote: '' }; }

const weekLabel = $('Process GSC data').first().json.weekLabel;
const weekOf = $('Process GSC data').first().json.weekOf;
const totalClicks = $('Process GSC data').first().json.totalClicks;
const totalImpressions = $('Process GSC data').first().json.totalImpressions;
const totalRows = $('Process GSC data').first().json.totalRows;

// Sanitize tone violations
const san = function(s) {
  return String(s || '')
    .replace(/!+/g, '.').replace(/\u2014/g, ',').replace(/ \u2013 /g, ', ')
    .replace(/\.{2,}/g, '.').replace(/,\s*,/g, ',').trim();
};
const sanObj = function(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const out = {};
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (typeof v === 'string') out[k] = san(v);
    else if (Array.isArray(v)) out[k] = v.map(function(x) { return typeof x === 'string' ? san(x) : (typeof x === 'object' ? sanObj(x) : x); });
    else if (typeof v === 'object') out[k] = sanObj(v);
    else out[k] = v;
  }
  return out;
};

map = sanObj(map);

// Build the seo_context payload for Supabase — this feeds the daily email all week
const priorityQueries = (map.topPriorities || []).map(function(p) { return p.query; });
const highKeywords = (map.keywords || []).filter(function(k) { return k.priority === 'high'; });
const medKeywords = (map.keywords || []).filter(function(k) { return k.priority === 'medium'; });
const allKeywords = highKeywords.concat(medKeywords);

const dailyContext = [
  'Week of ' + weekOf + '. ' + san(map.contextNote || ''),
  '',
  'Top priorities this week:',
].concat((map.topPriorities || []).map(function(p, i) {
  return (i + 1) + '. ' + p.query + ' — ' + san(p.angle || '');
})).concat([
  '',
  'Full keyword list (high + medium priority):',
]).concat(allKeywords.map(function(k) {
  return '- "' + k.query + '" [' + k.intent + ', ' + k.audience + ', ' + k.formatFit + '] — ' + san(k.angle || '');
})).join('\n');

const keywords_json = {
  week_of: weekOf,
  priorities: priorityQueries,
  keywords: (map.keywords || []).map(function(k) {
    return { query: k.query, intent: k.intent, audience: k.audience, formatFit: k.formatFit, priority: k.priority, angle: san(k.angle || '') };
  }),
  clusters: (map.clusters || []).map(function(c) {
    return { name: c.name, keywords: c.keywords || [], angle: san(c.angle || '') };
  }),
  contextNote: san(map.contextNote || ''),
  dailyContext: dailyContext
};

// Build HTML email
const esc = function(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
};

const priorityColor = { high: '#dc2626', medium: '#d97706', low: '#6b7280' };
const intentColor = { informational: '#3b82f6', commercial: '#059669', navigational: '#7c3aed' };
const audienceEmoji = { resellers: '💰', fashionistas: '✨', 'vintage community': '🧶', all: '👥' };

// GSC summary box
let html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>'
  + '<body style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;max-width:700px;margin:0 auto;padding:24px;color:#111">';

html += '<h1 style="font-size:20px;margin-bottom:4px">Crawli SEO keyword map — week of ' + esc(weekOf) + '</h1>';
html += '<p style="color:#6b7280;margin-top:0;margin-bottom:20px">Keyword research for the week. Saved to Supabase, feeds this week\'s daily content ideas.</p>';

html += '<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:24px">';
html += '<p style="margin:0 0 4px;font-size:13px;color:#6b7280">GSC last 28 days: ' + totalRows + ' queries, ' + totalClicks + ' clicks, ' + totalImpressions + ' impressions</p>';
html += '<p style="margin:0;font-size:14px">' + esc(map.gscSummary || '') + '</p>';
html += '</div>';

// Top priorities
html += '<h2 style="font-size:16px;margin-bottom:12px;border-bottom:2px solid #111;padding-bottom:6px">Top 3 priorities this week</h2>';
(map.topPriorities || []).forEach(function(p, i) {
  html += '<div style="margin-bottom:14px;padding:12px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px">';
  html += '<p style="margin:0 0 4px;font-weight:600">' + (i + 1) + '. ' + esc(p.query) + '</p>';
  html += '<p style="margin:0 0 3px;font-size:13px;color:#374151">' + esc(p.why) + '</p>';
  html += '<p style="margin:0;font-size:13px;color:#6b7280"><em>Angle: ' + esc(p.angle) + '</em></p>';
  html += '</div>';
});

// Full keyword list
html += '<h2 style="font-size:16px;margin:24px 0 12px;border-bottom:2px solid #111;padding-bottom:6px">Full keyword map (' + (map.keywords || []).length + ' keywords)</h2>';

['high', 'medium', 'low'].forEach(function(pri) {
  const group = (map.keywords || []).filter(function(k) { return k.priority === pri; });
  if (!group.length) return;
  html += '<p style="margin:12px 0 8px;font-weight:600;color:' + (priorityColor[pri] || '#6b7280') + '">' + pri.charAt(0).toUpperCase() + pri.slice(1) + ' priority (' + group.length + ')</p>';
  group.forEach(function(k) {
    const iColor = intentColor[k.intent] || '#6b7280';
    const aEmoji = audienceEmoji[k.audience] || '';
    html += '<div style="margin-bottom:10px;padding:10px 12px;border:1px solid #e5e7eb;border-left:3px solid ' + (priorityColor[pri] || '#6b7280') + ';border-radius:4px">';
    html += '<p style="margin:0 0 4px">';
    html += '<strong>' + esc(k.query) + '</strong>';
    html += ' <span style="background:' + iColor + ';color:#fff;font-size:11px;padding:1px 6px;border-radius:3px;margin-left:6px">' + esc(k.intent) + '</span>';
    html += ' <span style="font-size:12px;color:#6b7280;margin-left:4px">' + aEmoji + ' ' + esc(k.audience) + '</span>';
    html += ' <span style="font-size:12px;color:#6b7280;margin-left:4px">' + esc(k.gscPosition || '') + '</span>';
    html += ' <span style="font-size:11px;color:#6b7280;margin-left:4px">' + esc(k.formatFit) + '</span>';
    html += '</p>';
    html += '<p style="margin:0;font-size:13px;color:#374151">' + esc(k.angle) + '</p>';
    html += '</div>';
  });
});

// Topic clusters
if ((map.clusters || []).length > 0) {
  html += '<h2 style="font-size:16px;margin:24px 0 12px;border-bottom:2px solid #111;padding-bottom:6px">Topic clusters (' + map.clusters.length + ')</h2>';
  map.clusters.forEach(function(c) {
    html += '<div style="margin-bottom:12px;padding:10px 12px;border:1px solid #e5e7eb;border-radius:6px">';
    html += '<p style="margin:0 0 4px;font-weight:600">' + esc(c.name) + '</p>';
    html += '<p style="margin:0 0 4px;font-size:13px;color:#6b7280">' + (c.keywords || []).map(function(q) {
      return '<code style="background:#f3f4f6;padding:1px 5px;border-radius:3px;margin-right:3px">' + esc(q) + '</code>';
    }).join('') + '</p>';
    html += '<p style="margin:0;font-size:13px;color:#374151">' + esc(c.angle) + '</p>';
    html += '</div>';
  });
}

// Context note
html += '<div style="margin-top:24px;padding:12px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px">';
html += '<p style="margin:0 0 4px;font-size:12px;font-weight:600;color:#1d4ed8">DAILY CONTENT CONTEXT (saved to Supabase)</p>';
html += '<p style="margin:0;font-size:13px">' + esc(map.contextNote || '') + '</p>';
html += '</div>';

html += '</body></html>';

return [{ json: { html, subject: 'Crawli SEO map — week of ' + weekOf, keywords_json } }];
